preConditionHook:
// Rank of the current close among the last lookback closes (self
// included; the self-comparison is always false). Ties are generous:
// equal closes share the better rank, so a flat stretch ranks as top
// AND bottom -- both sides can fire on it, like the EL twin.
countAbove = 0;
countBelow = 0;
for (ii = 0; ii < (int)lookback; ++ii) {
    if (el_gt(close[ii], close[0])) countAbove = countAbove + 1;
    if (el_lt(close[ii], close[0])) countBelow = countBelow + 1;
}
